55	/**
56	 * Helper to check if a model ID looks like an alias (no date suffix)
57	 * Dates are typically in format: -20241022 or -20250929
58	 */
59	function isAlias(id: string): boolean {
60		// Check if ID ends with -latest
61		if (id.endsWith("-latest")) return true;
62	
63		// Check if ID ends with a date pattern (-YYYYMMDD)
64		const datePattern = /-\d{8}$/;
65		return !datePattern.test(id);
66	}
67	
68	/**
69	 * Find an exact model reference match.
70	 * Supports either a bare model id or a canonical provider/modelId reference.
71	 * When matching by bare id, ambiguous matches across providers are rejected.
72	 */
73	export function findExactModelReferenceMatch(
74		modelReference: string,
75		availableModels: Model<Api>[],
76	): Model<Api> | undefined {
77		const trimmedReference = modelReference.trim();
78		if (!trimmedReference) {
79			return undefined;
80		}
81	
82		const normalizedReference = trimmedReference.toLowerCase();
83	
84		const canonicalMatches = availableModels.filter(
85			(model) => `${model.provider}/${model.id}`.toLowerCase() === normalizedReference,
86		);
87		if (canonicalMatches.length === 1) {
88			return canonicalMatches[0];
89		}
90		if (canonicalMatches.length > 1) {
91			return undefined;
92		}
93	
94		const slashIndex = trimmedReference.indexOf("/");
95		if (slashIndex !== -1) {
96			const provider = trimmedReference.substring(0, slashIndex).trim();
97			const modelId = trimmedReference.substring(slashIndex + 1).trim();
98			if (provider && modelId) {
99				const providerMatches = availableModels.filter(
100					(model) =>
101						model.provider.toLowerCase() === provider.toLowerCase() &&
102						model.id.toLowerCase() === modelId.toLowerCase(),
103				);
104				if (providerMatches.length === 1) {
105					return providerMatches[0];
106				}
107				if (providerMatches.length > 1) {
108					return undefined;
109				}
110			}
111		}
112	
113		const idMatches = availableModels.filter((model) => model.id.toLowerCase() === normalizedReference);
114		return idMatches.length === 1 ? idMatches[0] : undefined;
115	}
