117	/**
118	 * Try to match a pattern to a model from the available models list.
119	 * Returns the matched model or undefined if no match found.
120	 */
121	function tryMatchModel(modelPattern: string, availableModels: Model<Api>[]): Model<Api> | undefined {
122		const exactMatch = findExactModelReferenceMatch(modelPattern, availableModels);
123		if (exactMatch) {
124			return exactMatch;
125		}
126	
127		// No exact match - fall back to partial matching
128		const matches = availableModels.filter(
129			(m) =>
130				m.id.toLowerCase().includes(modelPattern.toLowerCase()) ||
131				m.name?.toLowerCase().includes(modelPattern.toLowerCase()),
132		);
133	
134		if (matches.length === 0) {
135			return undefined;
136		}
137	
138		// Separate into aliases and dated versions
139		const aliases = matches.filter((m) => isAlias(m.id));
140		const datedVersions = matches.filter((m) => !isAlias(m.id));
141	
142		if (aliases.length > 0) {
143			// Prefer alias - if multiple aliases, pick the one that sorts highest
144			aliases.sort((a, b) => b.id.localeCompare(a.id));
145			return aliases[0];
146		} else {
147			// No alias found, pick latest dated version
148			datedVersions.sort((a, b) => b.id.localeCompare(a.id));
149			return datedVersions[0];
150		}
151	}
152	
153	export interface ParsedModelResult {
154		model: Model<Api> | undefined;
155		/** Thinking level if explicitly specified in pattern, undefined otherwise */
156		thinkingLevel?: ThinkingLevel;
157		warning: string | undefined;
158	}
159	
160	function buildFallbackModel(provider: string, modelId: string, availableModels: Model<Api>[]): Model<Api> | undefined {
161		const providerModels = availableModels.filter((m) => m.provider === provider);
162		if (providerModels.length === 0) return undefined;
163	
164		const defaultId = defaultModelPerProvider[provider as KnownProvider];
165		const baseModel = defaultId
166			? (providerModels.find((m) => m.id === defaultId) ?? providerModels[0])
167			: providerModels[0];
168	
169		return {
170			...baseModel,
171			id: modelId,
172			name: modelId,
173		};
174	}
175	
176	/**
177	 * Parse a pattern to extract model and thinking level.
178	 * Handles models with colons in their IDs (e.g., OpenRouter's :exacto suffix).
179	 *
180	 * Algorithm:
181	 * 1. Try to match full pattern as a model
182	 * 2. If found, return it with "off" thinking level
183	 * 3. If not found and has colons, split on last colon:
184	 *    - If suffix is valid thinking level, use it and recurse on prefix
185	 *    - If suffix is invalid, warn and recurse on prefix with "off"
186	 *
187	 * @internal Exported for testing
188	 */
189	export function parseModelPattern(
190		pattern: string,
191		availableModels: Model<Api>[],
192		options?: { allowInvalidThinkingLevelFallback?: boolean },
193	): ParsedModelResult {
194		// Try exact match first
195		const exactMatch = tryMatchModel(pattern, availableModels);
196		if (exactMatch) {
197			return { model: exactMatch, thinkingLevel: undefined, warning: undefined };
198		}
199	
200		// No match - try splitting on last colon if present
201		const lastColonIndex = pattern.lastIndexOf(":");
202		if (lastColonIndex === -1) {
203			// No colons, pattern simply doesn't match any model
204			return { model: undefined, thinkingLevel: undefined, warning: undefined };
205		}
206	
207		const prefix = pattern.substring(0, lastColonIndex);
208		const suffix = pattern.substring(lastColonIndex + 1);
209	
210		if (isValidThinkingLevel(suffix)) {
211			// Valid thinking level - recurse on prefix and use this level
212			const result = parseModelPattern(prefix, availableModels, options);
213			if (result.model) {
214				// Only use this thinking level if no warning from inner recursion
215				return {
216					model: result.model,
217					thinkingLevel: result.warning ? undefined : suffix,
218					warning: result.warning,
219				};
220			}
221			return result;
222		} else {
223			// Invalid suffix
224			const allowFallback = options?.allowInvalidThinkingLevelFallback ?? true;
225			if (!allowFallback) {
226				// In strict mode (CLI --model parsing), treat it as part of the model id and fail.
227				// This avoids accidentally resolving to a different model.
228				return { model: undefined, thinkingLevel: undefined, warning: undefined };
229			}
230	
231			// Scope mode: recurse on prefix and warn
232			const result = parseModelPattern(prefix, availableModels, options);
233			if (result.model) {
234				return {
235					model: result.model,
236					thinkingLevel: undefined,
237					warning: `Invalid thinking level "${suffix}" in pattern "${pattern}". Using default instead.`,
238				};
239			}
240			return result;
241		}
242	}
243	
244	/**
245	 * Resolve model patterns to actual Model objects with optional thinking levels
246	 * Format: "pattern:level" where :level is optional
247	 * For each pattern, finds all matching models and picks the best version:
248	 * 1. Prefer alias (e.g., claude-sonnet-4-5) over dated versions (claude-sonnet-4-5-20250929)
249	 * 2. If no alias, pick the latest dated version
250	 *
251	 * Supports models with colons in their IDs (e.g., OpenRouter's model:exacto).
252	 * The algorithm tries to match the full pattern first, then progressively
253	 * strips colon-suffixes to find a match.
254	 */
255	export async function resolveModelScope(patterns: string[], modelRegistry: ModelRegistry): Promise<ScopedModel[]> {
256		const availableModels = await modelRegistry.getAvailable();
257		const scopedModels: ScopedModel[] = [];
258	
259		for (const pattern of patterns) {
260			// Check if pattern contains glob characters
261			if (pattern.includes("*") || pattern.includes("?") || pattern.includes("[")) {
262				// Extract optional thinking level suffix (e.g., "provider/*:high")
263				const colonIdx = pattern.lastIndexOf(":");
264				let globPattern = pattern;
265				let thinkingLevel: ThinkingLevel | undefined;
266	
267				if (colonIdx !== -1) {
268					const suffix = pattern.substring(colonIdx + 1);
269					if (isValidThinkingLevel(suffix)) {
270						thinkingLevel = suffix;
271						globPattern = pattern.substring(0, colonIdx);
272					}
273				}
274	
275				// Match against "provider/modelId" format OR just model ID
276				// This allows "*sonnet*" to match without requiring "anthropic/*sonnet*"
277				const matchingModels = availableModels.filter((m) => {
278					const fullId = `${m.provider}/${m.id}`;
279					return minimatch(fullId, globPattern, { nocase: true }) || minimatch(m.id, globPattern, { nocase: true });
280				});
281	
282				if (matchingModels.length === 0) {
283					console.warn(chalk.yellow(`Warning: No models match pattern "${pattern}"`));
284					continue;
285				}
286	
287				for (const model of matchingModels) {
288					if (!scopedModels.find((sm) => modelsAreEqual(sm.model, model))) {
289						scopedModels.push({ model, thinkingLevel });
290					}
291				}
292				continue;
293			}
294	
295			const { model, thinkingLevel, warning } = parseModelPattern(pattern, availableModels);
296	
297			if (warning) {
298				console.warn(chalk.yellow(`Warning: ${warning}`));
299			}
300	
301			if (!model) {
302				console.warn(chalk.yellow(`Warning: No models match pattern "${pattern}"`));
303				continue;
304			}
305	
306			// Avoid duplicates
307			if (!scopedModels.find((sm) => modelsAreEqual(sm.model, model))) {
308				scopedModels.push({ model, thinkingLevel });
309			}
310		}
311	
312		return scopedModels;
313	}
314	
315	export interface ResolveCliModelResult {
316		model: Model<Api> | undefined;
317		thinkingLevel?: ThinkingLevel;
318		warning: string | undefined;
319		/**
320		 * Error message suitable for CLI display.
321		 * When set, model will be undefined.
322		 */
323		error: string | undefined;
324	}
325	
326	/**
327	 * Resolve a single model from CLI flags.
328	 *
329	 * Supports:
330	 * - --provider <provider> --model <pattern>
331	 * - --model <provider>/<pattern>
332	 * - Fuzzy matching (same rules as model scoping: exact id, then partial id/name)
333	 *
334	 * Note: This does not apply the thinking level by itself, but it may *parse* and
335	 * return a thinking level from "<pattern>:<thinking>" so the caller can apply it.
336	 */
337	export function resolveCliModel(options: {
338		cliProvider?: string;
339		cliModel?: string;
340		modelRegistry: ModelRegistry;
341	}): ResolveCliModelResult {
342		const { cliProvider, cliModel, modelRegistry } = options;
343	
344		if (!cliModel) {
345			return { model: undefined, warning: undefined, error: undefined };
346		}
347	
348		// Important: use *all* models here, not just models with pre-configured auth.
349		// This allows "--api-key" to be used for first-time setup.
350		const availableModels = modelRegistry.getAll();
351		if (availableModels.length === 0) {
352			return {
353				model: undefined,
354				warning: undefined,
355				error: "No models available. Check your installation or add models to models.json.",
356			};
357		}
358	
359		// Build canonical provider lookup (case-insensitive)
360		const providerMap = new Map<string, string>();
361		for (const m of availableModels) {
362			providerMap.set(m.provider.toLowerCase(), m.provider);
363		}
364	
365		let provider = cliProvider ? providerMap.get(cliProvider.toLowerCase()) : undefined;
366		if (cliProvider && !provider) {
367			return {
368				model: undefined,
369				warning: undefined,
370				error: `Unknown provider "${cliProvider}". Use --list-models to see available providers/models.`,
371			};
372		}
373	
374		// If no explicit --provider, try to interpret "provider/model" format first.
375		// When the prefix before the first slash matches a known provider, prefer that
376		// interpretation over matching models whose IDs literally contain slashes
377		// (e.g. "zai/glm-5" should resolve to provider=zai, model=glm-5, not to a
378		// vercel-ai-gateway model with id "zai/glm-5").
379		let pattern = cliModel;
380		let inferredProvider = false;
381	
382		if (!provider) {
383			const slashIndex = cliModel.indexOf("/");
384			if (slashIndex !== -1) {
385				const maybeProvider = cliModel.substring(0, slashIndex);
386				const canonical = providerMap.get(maybeProvider.toLowerCase());
387				if (canonical) {
388					provider = canonical;
389					pattern = cliModel.substring(slashIndex + 1);
390					inferredProvider = true;
391				}
392			}
393		}
394	
395		// If no provider was inferred from the slash, try exact matches without provider inference.
396		// This handles models whose IDs naturally contain slashes (e.g. OpenRouter-style IDs).
397		if (!provider) {
398			const lower = cliModel.toLowerCase();
399			const exact = availableModels.find(
400				(m) => m.id.toLowerCase() === lower || `${m.provider}/${m.id}`.toLowerCase() === lower,
401			);
402			if (exact) {
403				return { model: exact, warning: undefined, thinkingLevel: undefined, error: undefined };
404			}
405		}
406	
407		if (cliProvider && provider) {
408			// If both were provided, tolerate --model <provider>/<pattern> by stripping the provider prefix
409			const prefix = `${provider}/`;
410			if (cliModel.toLowerCase().startsWith(prefix.toLowerCase())) {
411				pattern = cliModel.substring(prefix.length);
412			}
413		}
414	
415		const candidates = provider ? availableModels.filter((m) => m.provider === provider) : availableModels;
416		const { model, thinkingLevel, warning } = parseModelPattern(pattern, candidates, {
417			allowInvalidThinkingLevelFallback: false,
418		});
419	
420		if (model) {
421			return { model, thinkingLevel, warning, error: undefined };
422		}
423	
424		// If we inferred a provider from the slash but found no match within that provider,
425		// fall back to matching the full input as a raw model id across all models.
426		// This handles OpenRouter-style IDs like "openai/gpt-4o:extended" where "openai"
427		// looks like a provider but the full string is actually a model id on openrouter.
428		if (inferredProvider) {
429			const lower = cliModel.toLowerCase();
430			const exact = availableModels.find(
431				(m) => m.id.toLowerCase() === lower || `${m.provider}/${m.id}`.toLowerCase() === lower,
432			);
433			if (exact) {
434				return { model: exact, warning: undefined, thinkingLevel: undefined, error: undefined };
435			}
436			// Also try parseModelPattern on the full input against all models
437			const fallback = parseModelPattern(cliModel, availableModels, {
438				allowInvalidThinkingLevelFallback: false,
439			});
440			if (fallback.model) {
441				return {
442					model: fallback.model,
443					thinkingLevel: fallback.thinkingLevel,
444					warning: fallback.warning,
445					error: undefined,
446				};
447			}
448		}
449	
450		if (provider) {
451			const fallbackModel = buildFallbackModel(provider, pattern, availableModels);
452			if (fallbackModel) {
453				const fallbackWarning = warning
454					? `${warning} Model "${pattern}" not found for provider "${provider}". Using custom model id.`
455					: `Model "${pattern}" not found for provider "${provider}". Using custom model id.`;
456				return { model: fallbackModel, thinkingLevel: undefined, warning: fallbackWarning, error: undefined };
457			}
458		}
459	
460		const display = provider ? `${provider}/${pattern}` : cliModel;
461		return {
462			model: undefined,
463			thinkingLevel: undefined,
464			warning,
465			error: `Model "${display}" not found. Use --list-models to see available models.`,
466		};
467	}
468	
469	export interface InitialModelResult {
470		model: Model<Api> | undefined;
471		thinkingLevel: ThinkingLevel;
472		fallbackMessage: string | undefined;
473	}
474	
475	/**
476	 * Find the initial model to use based on priority:
477	 * 1. CLI args (provider + model)
478	 * 2. First model from scoped models (if not continuing/resuming)
479	 * 3. Restored from session (if continuing/resuming)
480	 * 4. Saved default from settings
481	 * 5. First available model with valid API key
482	 */
483	export async function findInitialModel(options: {
484		cliProvider?: string;
485		cliModel?: string;
486		scopedModels: ScopedModel[];
487		isContinuing: boolean;
488		defaultProvider?: string;
489		defaultModelId?: string;
490		defaultThinkingLevel?: ThinkingLevel;
491		modelRegistry: ModelRegistry;
492	}): Promise<InitialModelResult> {
493		const {
494			cliProvider,
495			cliModel,
496			scopedModels,
497			isContinuing,
498			defaultProvider,
499			defaultModelId,
500			defaultThinkingLevel,
501			modelRegistry,
502		} = options;
503	
504		let model: Model<Api> | undefined;
505		let thinkingLevel: ThinkingLevel = DEFAULT_THINKING_LEVEL;
506	
507		// 1. CLI args take priority
508		if (cliProvider && cliModel) {
509			const resolved = resolveCliModel({
510				cliProvider,
511				cliModel,
512				modelRegistry,
513			});
514			if (resolved.error) {
515				console.error(chalk.red(resolved.error));
516				process.exit(1);
517			}
518			if (resolved.model) {
519				return { model: resolved.model, thinkingLevel: DEFAULT_THINKING_LEVEL, fallbackMessage: undefined };
520			}
521		}
522	
523		// 2. Use first model from scoped models (skip if continuing/resuming)
524		if (scopedModels.length > 0 && !isContinuing) {
525			return {
526				model: scopedModels[0].model,
527				thinkingLevel: scopedModels[0].thinkingLevel ?? defaultThinkingLevel ?? DEFAULT_THINKING_LEVEL,
528				fallbackMessage: undefined,
529			};
530		}
531	
532		// 3. Try saved default from settings
533		if (defaultProvider && defaultModelId) {
534			const found = modelRegistry.find(defaultProvider, defaultModelId);
535			if (found) {
536				model = found;
537				if (defaultThinkingLevel) {
538					thinkingLevel = defaultThinkingLevel;
539				}
540				return { model, thinkingLevel, fallbackMessage: undefined };
541			}
542		}
543	
544		// 4. Try first available model with valid API key
545		const availableModels = await modelRegistry.getAvailable();
546	
547		if (availableModels.length > 0) {
548			// Try to find a default model from known providers
549			for (const provider of Object.keys(defaultModelPerProvider) as KnownProvider[]) {
550				const defaultId = defaultModelPerProvider[provider];
551				const match = availableModels.find((m) => m.provider === provider && m.id === defaultId);
552				if (match) {
553					return { model: match, thinkingLevel: DEFAULT_THINKING_LEVEL, fallbackMessage: undefined };
554				}
555			}
556	
557			// If no default found, use first available
558			return { model: availableModels[0], thinkingLevel: DEFAULT_THINKING_LEVEL, fallbackMessage: undefined };
559		}
560	
561		// 5. No model found
562		return { model: undefined, thinkingLevel: DEFAULT_THINKING_LEVEL, fallbackMessage: undefined };
563	}
564	
565	/**
566	 * Restore model from session, with fallback to available models
567	 */
568	export async function restoreModelFromSession(
569		savedProvider: string,
570		savedModelId: string,
571		currentModel: Model<Api> | undefined,
572		shouldPrintMessages: boolean,
573		modelRegistry: ModelRegistry,
574	): Promise<{ model: Model<Api> | undefined; fallbackMessage: string | undefined }> {
575		const restoredModel = modelRegistry.find(savedProvider, savedModelId);
576	
577		// Check if restored model exists and still has auth configured
578		const hasConfiguredAuth = restoredModel ? modelRegistry.hasConfiguredAuth(restoredModel) : false;
579	
580		if (restoredModel && hasConfiguredAuth) {
581			if (shouldPrintMessages) {
582				console.log(chalk.dim(`Restored model: ${savedProvider}/${savedModelId}`));
583			}
584			return { model: restoredModel, fallbackMessage: undefined };
585		}
586	
587		// Model not found or no API key - fall back
588		const reason = !restoredModel ? "model no longer exists" : "no auth configured";
589	
590		if (shouldPrintMessages) {
591			console.error(chalk.yellow(`Warning: Could not restore model ${savedProvider}/${savedModelId} (${reason}).`));
592		}
593	
594		// If we already have a model, use it as fallback
595		if (currentModel) {
596			if (shouldPrintMessages) {
597				console.log(chalk.dim(`Falling back to: ${currentModel.provider}/${currentModel.id}`));
598			}
599			return {
600				model: currentModel,
601				fallbackMessage: `Could not restore model ${savedProvider}/${savedModelId} (${reason}). Using ${currentModel.provider}/${currentModel.id}.`,
602			};
603		}
604	
605		// Try to find any available model
606		const availableModels = await modelRegistry.getAvailable();
607	
608		if (availableModels.length > 0) {
609			// Try to find a default model from known providers
610			let fallbackModel: Model<Api> | undefined;
611			for (const provider of Object.keys(defaultModelPerProvider) as KnownProvider[]) {
612				const defaultId = defaultModelPerProvider[provider];
613				const match = availableModels.find((m) => m.provider === provider && m.id === defaultId);
614				if (match) {
615					fallbackModel = match;
616					break;
617				}
618			}
619	
620			// If no default found, use first available
621			if (!fallbackModel) {
622				fallbackModel = availableModels[0];
623			}
624	
625			if (shouldPrintMessages) {
626				console.log(chalk.dim(`Falling back to: ${fallbackModel.provider}/${fallbackModel.id}`));
627			}
628	
629			return {
630				model: fallbackModel,
631				fallbackMessage: `Could not restore model ${savedProvider}/${savedModelId} (${reason}). Using ${fallbackModel.provider}/${fallbackModel.id}.`,
632			};
633		}
634	
635		// No models available
636		return { model: undefined, fallbackMessage: undefined };
637	}
