177				cacheWrite: Type.Optional(Type.Number()),
178			}),
179		),
180		contextWindow: Type.Optional(Type.Number()),
181		maxTokens: Type.Optional(Type.Number()),
182		headers: Type.Optional(Type.Record(Type.String(), Type.String())),
183		compat: Type.Optional(ProviderCompatSchema),
184	});
185	
186	type ModelOverride = Static<typeof ModelOverrideSchema>;
187	
188	const ProviderConfigSchema = Type.Object({
189		name: Type.Optional(Type.String({ minLength: 1 })),
190		baseUrl: Type.Optional(Type.String({ minLength: 1 })),
191		apiKey: Type.Optional(Type.String({ minLength: 1 })),
192		api: Type.Optional(Type.String({ minLength: 1 })),
193		headers: Type.Optional(Type.Record(Type.String(), Type.String())),
194		compat: Type.Optional(ProviderCompatSchema),
195		authHeader: Type.Optional(Type.Boolean()),
196		models: Type.Optional(Type.Array(ModelDefinitionSchema)),
197		modelOverrides: Type.Optional(Type.Record(Type.String(), ModelOverrideSchema)),
198	});
199	
200	const ModelsConfigSchema = Type.Object({
201		providers: Type.Record(Type.String(), ProviderConfigSchema),
202	});
203	
204	const validateModelsConfig = Compile(ModelsConfigSchema);
205	
206	type ModelsConfig = Static<typeof ModelsConfigSchema>;
207	
208	function formatValidationPath(error: TLocalizedValidationError): string {
209		if (error.keyword === "required") {
210			const requiredProperties = (error.params as { requiredProperties?: string[] }).requiredProperties;
211			const requiredProperty = requiredProperties?.[0];
212			if (requiredProperty) {
213				const basePath = error.instancePath.replace(/^\//, "").replace(/\//g, ".");
214				return basePath ? `${basePath}.${requiredProperty}` : requiredProperty;
215			}
216		}
217		const path = error.instancePath.replace(/^\//, "").replace(/\//g, ".");
218		return path || "root";
219	}
220	
221	/** Strip `//` line comments and trailing commas from JSON, leaving string literals untouched. */
222	function stripJsonComments(input: string): string {
223		return input
224			.replace(/"(?:\\.|[^"\\])*"|\/\/[^\n]*/g, (m) => (m[0] === '"' ? m : ""))
225			.replace(/"(?:\\.|[^"\\])*"|,(\s*[}\]])/g, (m, tail) => tail ?? (m[0] === '"' ? m : ""));
226	}
