228	/** Provider override config (baseUrl, compat) without request auth/headers */
229	interface ProviderOverride {
230		baseUrl?: string;
231		compat?: Model<Api>["compat"];
232	}
233	
234	interface ProviderRequestConfig {
235		apiKey?: string;
236		headers?: Record<string, string>;
237		authHeader?: boolean;
238	}
239	
240	export type ResolvedRequestAuth =
241		| {
242				ok: true;
243				apiKey?: string;
244				headers?: Record<string, string>;
245		  }
246		| {
247				ok: false;
248				error: string;
249		  };
250	
251	/** Result of loading custom models from models.json */
252	interface CustomModelsResult {
253		models: Model<Api>[];
254		/** Providers with baseUrl/headers/apiKey overrides for built-in models */
255		overrides: Map<string, ProviderOverride>;
256		/** Per-model overrides: provider -> modelId -> override */
257		modelOverrides: Map<string, Map<string, ModelOverride>>;
258		error: string | undefined;
259	}
260	
261	function emptyCustomModelsResult(error?: string): CustomModelsResult {
262		return { models: [], overrides: new Map(), modelOverrides: new Map(), error };
263	}
264	
265	function mergeCompat(
266		baseCompat: Model<Api>["compat"],
267		overrideCompat: ModelOverride["compat"],
268	): Model<Api>["compat"] | undefined {
269		if (!overrideCompat) return baseCompat;
270	
271		const base = baseCompat as OpenAICompletionsCompat | OpenAIResponsesCompat | AnthropicMessagesCompat | undefined;
272		const override = overrideCompat as OpenAICompletionsCompat | OpenAIResponsesCompat | AnthropicMessagesCompat;
273		const merged = { ...base, ...override } as OpenAICompletionsCompat | OpenAIResponsesCompat | AnthropicMessagesCompat;
274	
275		const baseCompletions = base as OpenAICompletionsCompat | undefined;
276		const overrideCompletions = override as OpenAICompletionsCompat;
277		const mergedCompletions = merged as OpenAICompletionsCompat;
278	
279		if (baseCompletions?.openRouterRouting || overrideCompletions.openRouterRouting) {
280			mergedCompletions.openRouterRouting = {
281				...baseCompletions?.openRouterRouting,
282				...overrideCompletions.openRouterRouting,
283			};
284		}
285	
286		if (baseCompletions?.vercelGatewayRouting || overrideCompletions.vercelGatewayRouting) {
287			mergedCompletions.vercelGatewayRouting = {
288				...baseCompletions?.vercelGatewayRouting,
289				...overrideCompletions.vercelGatewayRouting,
290			};
291		}
292	
293		return merged as Model<Api>["compat"];
294	}
295	
296	/**
297	 * Deep merge a model override into a model.
298	 * Handles nested objects (cost, compat) by merging rather than replacing.
299	 */
300	function applyModelOverride(model: Model<Api>, override: ModelOverride): Model<Api> {
301		const result = { ...model };
302	
303		// Simple field overrides
304		if (override.name !== undefined) result.name = override.name;
305		if (override.reasoning !== undefined) result.reasoning = override.reasoning;
306		if (override.thinkingLevelMap !== undefined) {
307			result.thinkingLevelMap = { ...model.thinkingLevelMap, ...override.thinkingLevelMap };
308		}
309		if (override.input !== undefined) result.input = override.input as ("text" | "image")[];
310		if (override.contextWindow !== undefined) result.contextWindow = override.contextWindow;
311		if (override.maxTokens !== undefined) result.maxTokens = override.maxTokens;
312	
313		// Merge cost (partial override)
314		if (override.cost) {
315			result.cost = {
316				input: override.cost.input ?? model.cost.input,
317				output: override.cost.output ?? model.cost.output,
318				cacheRead: override.cost.cacheRead ?? model.cost.cacheRead,
319				cacheWrite: override.cost.cacheWrite ?? model.cost.cacheWrite,
320			};
321		}
322	
323		// Deep merge compat
324		result.compat = mergeCompat(model.compat, override.compat);
325	
326		return result;
327	}
