332	/**
333	 * Model registry - loads and manages models, resolves API keys via AuthStorage.
334	 */
335	export class ModelRegistry {
336		private models: Model<Api>[] = [];
337		private providerRequestConfigs: Map<string, ProviderRequestConfig> = new Map();
338		private modelRequestHeaders: Map<string, Record<string, string>> = new Map();
339		private registeredProviders: Map<string, ProviderConfigInput> = new Map();
340		private loadError: string | undefined = undefined;
341		readonly authStorage: AuthStorage;
342		private modelsJsonPath: string | undefined;
343	
344		private constructor(authStorage: AuthStorage, modelsJsonPath: string | undefined) {
345			this.authStorage = authStorage;
346			this.modelsJsonPath = modelsJsonPath ? normalizePath(modelsJsonPath) : undefined;
347			this.loadModels();
348		}
349	
350		static create(authStorage: AuthStorage, modelsJsonPath: string = join(getAgentDir(), "models.json")): ModelRegistry {
351			return new ModelRegistry(authStorage, modelsJsonPath);
352		}
353	
354		static inMemory(authStorage: AuthStorage): ModelRegistry {
355			return new ModelRegistry(authStorage, undefined);
356		}
357	
358		/**
359		 * Reload models from disk (built-in + custom from models.json).
360		 */
361		refresh(): void {
362			this.providerRequestConfigs.clear();
363			this.modelRequestHeaders.clear();
364			this.loadError = undefined;
365	
366			// Ensure dynamic API/OAuth registrations are rebuilt from current provider state.
367			resetApiProviders();
368			resetOAuthProviders();
369	
370			this.loadModels();
371	
372			for (const [providerName, config] of this.registeredProviders.entries()) {
373				this.applyProviderConfig(providerName, config);
374			}
375		}
376	
377		/**
378		 * Get any error from loading models.json (undefined if no error).
379		 */
380		getError(): string | undefined {
381			return this.loadError;
382		}
383	
384		private loadModels(): void {
385			// Load custom models and overrides from models.json
386			const {
387				models: customModels,
388				overrides,
389				modelOverrides,
390				error,
391			} = this.modelsJsonPath ? this.loadCustomModels(this.modelsJsonPath) : emptyCustomModelsResult();
392	
393			if (error) {
394				this.loadError = error;
395				// Keep built-in models even if custom models failed to load
396			}
397	
398			const builtInModels = this.loadBuiltInModels(overrides, modelOverrides);
399			let combined = this.mergeCustomModels(builtInModels, customModels);
400	
401			// Let OAuth providers modify their models (e.g., update baseUrl)
402			for (const oauthProvider of this.authStorage.getOAuthProviders()) {
403				const cred = this.authStorage.get(oauthProvider.id);
404				if (cred?.type === "oauth" && oauthProvider.modifyModels) {
405					combined = oauthProvider.modifyModels(combined, cred);
406				}
407			}
408	
409			this.models = combined;
410		}
411	
412		/** Load built-in models and apply provider/model overrides */
413		private loadBuiltInModels(
414			overrides: Map<string, ProviderOverride>,
415			modelOverrides: Map<string, Map<string, ModelOverride>>,
416		): Model<Api>[] {
417			return getProviders().flatMap((provider) => {
418				const models = getModels(provider as KnownProvider) as Model<Api>[];
419				const providerOverride = overrides.get(provider);
420				const perModelOverrides = modelOverrides.get(provider);
421	
422				return models.map((m) => {
423					let model = m;
424	
425					// Apply provider-level baseUrl/headers/compat override
426					if (providerOverride) {
427						model = {
428							...model,
429							baseUrl: providerOverride.baseUrl ?? model.baseUrl,
430							compat: mergeCompat(model.compat, providerOverride.compat),
431						};
432					}
433	
434					// Apply per-model override
435					const modelOverride = perModelOverrides?.get(m.id);
436					if (modelOverride) {
437						model = applyModelOverride(model, modelOverride);
438					}
439	
440					return model;
441				});
442			});
443		}
444	
445		/** Merge custom models into built-in list by provider+id (custom wins on conflicts). */
446		private mergeCustomModels(builtInModels: Model<Api>[], customModels: Model<Api>[]): Model<Api>[] {
447			const merged = [...builtInModels];
448			for (const customModel of customModels) {
449				const existingIndex = merged.findIndex((m) => m.provider === customModel.provider && m.id === customModel.id);
450				if (existingIndex >= 0) {
451					merged[existingIndex] = customModel;
452				} else {
453					merged.push(customModel);
454				}
455			}
456			return merged;
457		}
458	
459		private loadCustomModels(modelsJsonPath: string): CustomModelsResult {
460			if (!existsSync(modelsJsonPath)) {
461				return emptyCustomModelsResult();
462			}
463	
464			try {
465				const content = readFileSync(modelsJsonPath, "utf-8");
466				const parsed = JSON.parse(stripJsonComments(content)) as unknown;
467	
468				if (!validateModelsConfig.Check(parsed)) {
469					const errors =
470						validateModelsConfig
471							.Errors(parsed)
472							.map((error) => `  - ${formatValidationPath(error)}: ${error.message}`)
473							.join("\n") || "Unknown schema error";
474					return emptyCustomModelsResult(`Invalid models.json schema:\n${errors}\n\nFile: ${modelsJsonPath}`);
475				}
476	
477				const config = parsed as ModelsConfig;
478	
479				// Additional validation
480				this.validateConfig(config);
481	
482				const overrides = new Map<string, ProviderOverride>();
483				const modelOverrides = new Map<string, Map<string, ModelOverride>>();
484	
485				for (const [providerName, providerConfig] of Object.entries(config.providers)) {
486					if (providerConfig.baseUrl || providerConfig.compat) {
487						overrides.set(providerName, {
488							baseUrl: providerConfig.baseUrl,
489							compat: providerConfig.compat,
490						});
491					}
492	
493					this.storeProviderRequestConfig(providerName, providerConfig);
494	
495					if (providerConfig.modelOverrides) {
496						modelOverrides.set(providerName, new Map(Object.entries(providerConfig.modelOverrides)));
497						for (const [modelId, modelOverride] of Object.entries(providerConfig.modelOverrides)) {
498							this.storeModelHeaders(providerName, modelId, modelOverride.headers);
499						}
500					}
501				}
502	
503				return { models: this.parseModels(config), overrides, modelOverrides, error: undefined };
504			} catch (error) {
505				if (error instanceof SyntaxError) {
506					return emptyCustomModelsResult(`Failed to parse models.json: ${error.message}\n\nFile: ${modelsJsonPath}`);
507				}
508				return emptyCustomModelsResult(
509					`Failed to load models.json: ${error instanceof Error ? error.message : error}\n\nFile: ${modelsJsonPath}`,
510				);
511			}
512		}
513	
514		private validateConfig(config: ModelsConfig): void {
515			const builtInProviders = new Set<string>(getProviders());
516	
517			for (const [providerName, providerConfig] of Object.entries(config.providers)) {
518				const isBuiltIn = builtInProviders.has(providerName);
519				const hasProviderApi = !!providerConfig.api;
520				const models = providerConfig.models ?? [];
521				const hasModelOverrides =
522					providerConfig.modelOverrides && Object.keys(providerConfig.modelOverrides).length > 0;
523	
524				if (models.length === 0) {
525					// Override-only config: needs baseUrl, headers, compat, modelOverrides, or some combination.
526					if (!providerConfig.baseUrl && !providerConfig.headers && !providerConfig.compat && !hasModelOverrides) {
527						throw new Error(
528							`Provider ${providerName}: must specify "baseUrl", "headers", "compat", "modelOverrides", or "models".`,
529						);
530					}
531				} else if (!isBuiltIn) {
532					// Non-built-in providers with custom models require endpoint + auth.
533					if (!providerConfig.baseUrl) {
534						throw new Error(`Provider ${providerName}: "baseUrl" is required when defining custom models.`);
535					}
536					if (!providerConfig.apiKey) {
537						throw new Error(`Provider ${providerName}: "apiKey" is required when defining custom models.`);
538					}
539				}
540				// Built-in providers with custom models: baseUrl/apiKey/api are optional,
541				// inherited from built-in models. Auth comes from env vars / auth storage.
542	
543				for (const modelDef of models) {
544					const hasModelApi = !!modelDef.api;
545	
546					if (!hasProviderApi && !hasModelApi && !isBuiltIn) {
547						throw new Error(
548							`Provider ${providerName}, model ${modelDef.id}: no "api" specified. Set at provider or model level.`,
549						);
550					}
551					// For built-in providers, api is optional — inherited from built-in models.
552	
553					if (!modelDef.id) throw new Error(`Provider ${providerName}: model missing "id"`);
554					// Validate contextWindow/maxTokens only if provided (they have defaults)
555					if (modelDef.contextWindow !== undefined && modelDef.contextWindow <= 0)
556						throw new Error(`Provider ${providerName}, model ${modelDef.id}: invalid contextWindow`);
557					if (modelDef.maxTokens !== undefined && modelDef.maxTokens <= 0)
558						throw new Error(`Provider ${providerName}, model ${modelDef.id}: invalid maxTokens`);
559				}
560			}
561		}
562	
563		private parseModels(config: ModelsConfig): Model<Api>[] {
564			const models: Model<Api>[] = [];
565			const builtInProviders = new Set<string>(getProviders());
566	
567			// Cache built-in defaults (api, baseUrl) per provider, extracted from first model.
568			const builtInDefaultsCache = new Map<string, { api: string; baseUrl: string }>();
569			const getBuiltInDefaults = (providerName: string): { api: string; baseUrl: string } | undefined => {
570				if (!builtInProviders.has(providerName)) return undefined;
571				if (builtInDefaultsCache.has(providerName)) return builtInDefaultsCache.get(providerName);
572				const builtIn = getModels(providerName as KnownProvider) as Model<Api>[];
573				if (builtIn.length === 0) return undefined;
574				const defaults = { api: builtIn[0].api, baseUrl: builtIn[0].baseUrl };
575				builtInDefaultsCache.set(providerName, defaults);
576				return defaults;
577			};
578	
579			for (const [providerName, providerConfig] of Object.entries(config.providers)) {
580				const modelDefs = providerConfig.models ?? [];
581				if (modelDefs.length === 0) continue; // Override-only, no custom models
582	
583				const builtInDefaults = getBuiltInDefaults(providerName);
584	
585				for (const modelDef of modelDefs) {
586					const api = modelDef.api ?? providerConfig.api ?? builtInDefaults?.api;
587					if (!api) continue;
588	
589					const baseUrl = modelDef.baseUrl ?? providerConfig.baseUrl ?? builtInDefaults?.baseUrl;
590					if (!baseUrl) continue;
591	
592					const compat = mergeCompat(providerConfig.compat, modelDef.compat);
593					this.storeModelHeaders(providerName, modelDef.id, modelDef.headers);
594	
595					const defaultCost = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 };
596					models.push({
597						id: modelDef.id,
598						name: modelDef.name ?? modelDef.id,
599						api: api as Api,
600						provider: providerName,
601						baseUrl,
602						reasoning: modelDef.reasoning ?? false,
603						thinkingLevelMap: modelDef.thinkingLevelMap,
604						input: (modelDef.input ?? ["text"]) as ("text" | "image")[],
605						cost: modelDef.cost ?? defaultCost,
606						contextWindow: modelDef.contextWindow ?? 128000,
607						maxTokens: modelDef.maxTokens ?? 16384,
608						headers: undefined,
609						compat,
610					} as Model<Api>);
611				}
612			}
613	
614			return models;
615		}
