650		private getModelRequestKey(provider: string, modelId: string): string {
651			return `${provider}:${modelId}`;
652		}
653	
654		private storeProviderRequestConfig(
655			providerName: string,
656			config: {
657				apiKey?: string;
658				headers?: Record<string, string>;
659				authHeader?: boolean;
660			},
661		): void {
662			if (!config.apiKey && !config.headers && !config.authHeader) {
663				return;
664			}
665	
666			this.providerRequestConfigs.set(providerName, {
667				apiKey: config.apiKey,
668				headers: config.headers,
669				authHeader: config.authHeader,
670			});
671		}
672	
673		private storeModelHeaders(providerName: string, modelId: string, headers?: Record<string, string>): void {
674			const key = this.getModelRequestKey(providerName, modelId);
675			if (!headers || Object.keys(headers).length === 0) {
676				this.modelRequestHeaders.delete(key);
677				return;
678			}
679			this.modelRequestHeaders.set(key, headers);
680		}
681	
682		/**
683		 * Get API key and request headers for a model.
684		 */
685		async getApiKeyAndHeaders(model: Model<Api>): Promise<ResolvedRequestAuth> {
686			try {
687				const providerConfig = this.providerRequestConfigs.get(model.provider);
688				const apiKeyFromAuthStorage = await this.authStorage.getApiKey(model.provider, { includeFallback: false });
689				const apiKey =
690					apiKeyFromAuthStorage ??
691					(providerConfig?.apiKey
692						? resolveConfigValueOrThrow(providerConfig.apiKey, `API key for provider "${model.provider}"`)
693						: undefined);
694	
695				const providerHeaders = resolveHeadersOrThrow(providerConfig?.headers, `provider "${model.provider}"`);
696				const modelHeaders = resolveHeadersOrThrow(
697					this.modelRequestHeaders.get(this.getModelRequestKey(model.provider, model.id)),
698					`model "${model.provider}/${model.id}"`,
699				);
700	
701				let headers =
702					model.headers || providerHeaders || modelHeaders
703						? { ...model.headers, ...providerHeaders, ...modelHeaders }
704						: undefined;
705	
706				if (providerConfig?.authHeader) {
707					if (!apiKey) {
708						return { ok: false, error: `No API key found for "${model.provider}"` };
709					}
710					headers = { ...headers, Authorization: `Bearer ${apiKey}` };
711				}
712	
713				return {
714					ok: true,
715					apiKey,
716					headers: headers && Object.keys(headers).length > 0 ? headers : undefined,
717				};
718			} catch (error) {
719				return {
720					ok: false,
721					error: error instanceof Error ? error.message : String(error),
722				};
723			}
724		}
725	
726		/**
727		 * Return auth status for a provider, including request auth configured in models.json.
728		 * This intentionally does not execute command-backed config values.
729		 */
730		getProviderAuthStatus(provider: string): AuthStatus {
731			const authStatus = this.authStorage.getAuthStatus(provider);
732			if (authStatus.source) {
733				return authStatus;
734			}
735	
736			const providerApiKey = this.providerRequestConfigs.get(provider)?.apiKey;
737			if (!providerApiKey) {
738				return authStatus;
739			}
740	
741			if (providerApiKey.startsWith("!")) {
742				return { configured: true, source: "models_json_command" };
743			}
744	
745			if (process.env[providerApiKey]) {
746				return { configured: true, source: "environment", label: providerApiKey };
747			}
748	
749			return { configured: true, source: "models_json_key" };
750		}
751	
752		/**
753		 * Get display name for a provider.
754		 */
755		getProviderDisplayName(provider: string): string {
756			const registeredProvider = this.registeredProviders.get(provider);
757			const oauthProvider = this.authStorage.getOAuthProviders().find((p) => p.id === provider);
758	
759			return (
760				registeredProvider?.name ??
761				registeredProvider?.oauth?.name ??
762				oauthProvider?.name ??
763				BUILT_IN_PROVIDER_DISPLAY_NAMES[provider] ??
764				provider
765			);
766		}
767	
768		/**
769		 * Get API key for a provider.
770		 */
771		async getApiKeyForProvider(provider: string): Promise<string | undefined> {
772			const apiKey = await this.authStorage.getApiKey(provider, { includeFallback: false });
773			if (apiKey !== undefined) {
774				return apiKey;
775			}
776	
777			const providerApiKey = this.providerRequestConfigs.get(provider)?.apiKey;
778			return providerApiKey ? resolveConfigValueUncached(providerApiKey) : undefined;
779		}
