781		/**
782		 * Check if a model is using OAuth credentials (subscription).
783		 */
784		isUsingOAuth(model: Model<Api>): boolean {
785			const cred = this.authStorage.get(model.provider);
786			return cred?.type === "oauth";
787		}
788	
789		/**
790		 * Register a provider dynamically (from extensions).
791		 *
792		 * If provider has models: replaces all existing models for this provider.
793		 * If provider has only baseUrl/headers: overrides existing models' URLs.
794		 * If provider has oauth: registers OAuth provider for /login support.
795		 */
796		registerProvider(providerName: string, config: ProviderConfigInput): void {
797			this.validateProviderConfig(providerName, config);
798			this.applyProviderConfig(providerName, config);
799			this.upsertRegisteredProvider(providerName, config);
800		}
801	
802		/**
803		 * Unregister a previously registered provider.
804		 *
805		 * Removes the provider from the registry and reloads models from disk so that
806		 * built-in models overridden by this provider are restored to their original state.
807		 * Also resets dynamic OAuth and API stream registrations before reapplying
808		 * remaining dynamic providers.
809		 * Has no effect if the provider was never registered.
810		 */
811		unregisterProvider(providerName: string): void {
812			if (!this.registeredProviders.has(providerName)) return;
813			this.registeredProviders.delete(providerName);
814			this.refresh();
815		}
816	
817		/**
818		 * Upsert a provider config into registeredProviders.
819		 * If the provider is already registered, defined values in the incoming config
820		 * override existing ones; undefined values are preserved from the stored config.
821		 * If the provider is not registered, the incoming config is stored as-is.
822		 */
823		private upsertRegisteredProvider(providerName: string, config: ProviderConfigInput): void {
824			const existing = this.registeredProviders.get(providerName);
825			if (!existing) {
826				this.registeredProviders.set(providerName, config);
827				return;
828			}
829			for (const k of Object.keys(config) as (keyof ProviderConfigInput)[]) {
830				if (config[k] !== undefined) {
831					(existing as Record<string, unknown>)[k] = config[k];
832				}
833			}
834		}
835	
836		private validateProviderConfig(providerName: string, config: ProviderConfigInput): void {
837			if (config.streamSimple && !config.api) {
838				throw new Error(`Provider ${providerName}: "api" is required when registering streamSimple.`);
839			}
840	
841			if (!config.models || config.models.length === 0) {
842				return;
843			}
844	
845			if (!config.baseUrl) {
846				throw new Error(`Provider ${providerName}: "baseUrl" is required when defining models.`);
847			}
848			if (!config.apiKey && !config.oauth) {
849				throw new Error(`Provider ${providerName}: "apiKey" or "oauth" is required when defining models.`);
850			}
851	
852			for (const modelDef of config.models) {
853				const api = modelDef.api || config.api;
854				if (!api) {
855					throw new Error(`Provider ${providerName}, model ${modelDef.id}: no "api" specified.`);
856				}
857			}
858		}
859	
860		private applyProviderConfig(providerName: string, config: ProviderConfigInput): void {
861			// Register OAuth provider if provided
862			if (config.oauth) {
863				// Ensure the OAuth provider ID matches the provider name
864				const oauthProvider: OAuthProviderInterface = {
865					...config.oauth,
866					id: providerName,
867				};
868				registerOAuthProvider(oauthProvider);
869			}
870	
871			if (config.streamSimple) {
872				const streamSimple = config.streamSimple;
873				registerApiProvider(
874					{
875						api: config.api!,
876						stream: (model, context, options) => streamSimple(model, context, options as SimpleStreamOptions),
877						streamSimple,
878					},
879					`provider:${providerName}`,
880				);
881			}
882	
883			this.storeProviderRequestConfig(providerName, config);
884	
885			if (config.models && config.models.length > 0) {
886				// Full replacement: remove existing models for this provider
887				this.models = this.models.filter((m) => m.provider !== providerName);
888	
889				// Parse and add new models
890				for (const modelDef of config.models) {
891					const api = modelDef.api || config.api;
892					this.storeModelHeaders(providerName, modelDef.id, modelDef.headers);
893	
894					this.models.push({
895						id: modelDef.id,
896						name: modelDef.name,
897						api: api as Api,
898						provider: providerName,
899						baseUrl: modelDef.baseUrl ?? config.baseUrl!,
900						reasoning: modelDef.reasoning,
901						thinkingLevelMap: modelDef.thinkingLevelMap,
902						input: modelDef.input as ("text" | "image")[],
903						cost: modelDef.cost,
904						contextWindow: modelDef.contextWindow,
905						maxTokens: modelDef.maxTokens,
906						headers: undefined,
907						compat: modelDef.compat,
908					} as Model<Api>);
909				}
910	
911				// Apply OAuth modifyModels if credentials exist (e.g., to update baseUrl)
912				if (config.oauth?.modifyModels) {
913					const cred = this.authStorage.get(providerName);
914					if (cred?.type === "oauth") {
915						this.models = config.oauth.modifyModels(this.models, cred);
916					}
917				}
918			} else if (config.baseUrl || config.headers) {
919				// Override-only: update baseUrl for existing models. Request headers are resolved per request.
920				this.models = this.models.map((m) => {
921					if (m.provider !== providerName) return m;
922					return {
923						...m,
924						baseUrl: config.baseUrl ?? m.baseUrl,
925					};
926				});
927			}
928		}
929	}
930	
931	/**
932	 * Input type for registerProvider API.
933	 */
934	export interface ProviderConfigInput {
935		name?: string;
936		baseUrl?: string;
937		apiKey?: string;
938		api?: Api;
939		streamSimple?: (model: Model<Api>, context: Context, options?: SimpleStreamOptions) => AssistantMessageEventStream;
940		headers?: Record<string, string>;
941		authHeader?: boolean;
942		/** OAuth provider for /login support */
943		oauth?: Omit<OAuthProviderInterface, "id">;
944		models?: Array<{
945			id: string;
946			name: string;
947			api?: Api;
948			baseUrl?: string;
949			reasoning: boolean;
950			thinkingLevelMap?: Model<Api>["thinkingLevelMap"];
951			input: ("text" | "image")[];
952			cost: { input: number; output: number; cacheRead: number; cacheWrite: number };
953			contextWindow: number;
954			maxTokens: number;
955			headers?: Record<string, string>;
956			compat?: Model<Api>["compat"];
957		}>;
958	}
